def master():
    out=['This is the current source-reviewed learning entry point for the **Sprint 07 local implementation**, inspected 2026-10-08 at Git `ef196c9`. Learn the business and one request first; use inventories for navigation after you understand the flow. Existing Word handbooks and sprint evidence are preserved.','', '## Learning sequence','','For each topic, the linked chapter supplies its full internal explanation; the prompts below turn reading into an exercise. “What if removed” is a counterfactual learning question, not a request to alter the application.','']
    for i,(topic,chapter,exercise,where) in enumerate(TOPICS,1):
        title,body=chapters.get(chapter,('', ''))
        reason={'Authentication':'establish a live identity before domain access','Authorization':'enforce action permissions beyond sign-in','Multitenancy':'keep organization and project data isolated','Resource and capacity':'avoid misleading workload claims from incomplete data','Assessment engine':'keep scoring reproducible across framework changes','Command center':'make health reconcile with authorized evidence','AI architecture':'prevent planned intelligence from being presented as working code'}.get(topic,'understand the concrete implementation and its correctness boundary')
        what,example,internal,removed,question=DETAILS[i-1]
        out += [f'### {i}. [{topic}]({chapter}.md)','',f'**What:** {what}. **Why:** {reason}. **Where in this project:** `{where}`. **How:** {exercise}. **Internal working:** {internal}. **Example:** {example}. **What if removed:** {removed}. **Interview question:** {question}','']
    out+=['## Beginner → intermediate → advanced practice','','Beginner: draw browser→proxy→middleware→Auth→domain→Core→PostgreSQL→response, label every arrow, and distinguish project facts from dashboard output. Intermediate: trace project create/update, derive capacity and assessment examples, then explain 401/403/404/409/412/422/428 with code. Advanced: reason through lock contention, RLS pool reuse, refresh replay, immutable corrections, file/database atomicity and 10x/100x proposals.','', '## Complete chapter map','']
    for p in sorted(DOCS.glob('[0-3][0-9]-*.md')):
        out.append(f'- [{p.read_text(encoding="utf-8").splitlines()[0].removeprefix("# ")}]({p.name})')
    out+=['', '## Reference companions','', '- [Complete database dictionary](DATABASE-DICTIONARY.md)', '- [Code and test index](CODE-AND-TEST-INDEX.md)', '- [Feature evidence register](26-feature-status.md)', '- [Requirements coverage and verification](LEARNING-DOCUMENTATION-VERIFICATION.md)', '', 'Maintain this guide by updating narratives after source changes, regenerating source-derived inventories with `docs/learning/build_learning_docs.py`, checking links/contracts, and recording a new snapshot. The authored chapter scripts are documentation build helpers only; no database connection or migration execution is needed. Avoid rerunning an older authored snapshot over manually revised chapters without reviewing its diff.']
    write('AI-PPM-MASTER-LEARNING-GUIDE.md','AI-PPM MASTER LEARNING GUIDE','\n'.join(out))

